<script setup>import{Head}from'@inertiajs/vue3';import AdminLayout from '../../../Layouts/AdminLayout.vue';import DataPanel from '../../../Components/Ui/DataPanel.vue';import EmptyState from '../../../Components/Ui/EmptyState.vue';import PageHeader from '../../../Components/Ui/PageHeader.vue';defineOptions({layout:AdminLayout});defineProps({supplier:{type:Object,required:true},rows:{type:Array,default:()=>[]},urls:{type:Object,required:true}});const deltaTone=n=>n===null?'muted':Math.abs(n)<.01?'muted':n>0?'up':'down';</script>
<template><Head :title="`أسعار ${supplier.name}`"/><PageHeader :title="`أسعار ${supplier.name}`" icon="bi-truck" subtitle="آخر سعر لكل مكوّن والتغير خلال 30 يوماً" :crumbs="[{label:'ملف المورد',url:urls.supplier}]"><template #actions><a :href="urls.compare" class="btn btn-primary"><i class="bi bi-arrows-collapse"></i> مقارنة كل الموردين</a></template></PageHeader><DataPanel :title="`المكونات المورّدة من ${supplier.name}`" :count="rows.length" icon="bi-tags-fill"><div v-if="rows.length" class="supplier-prices"><a v-for="row in rows" :key="row.id" :href="row.url"><div><strong>{{row.ingredient}}</strong><small>SKU: {{row.sku||'—'}}</small></div><span><small>آخر سعر مدفوع</small><b>{{row.paidPrice}}</b></span><span><small>للوحدة الأساسية</small><b class="green">{{row.basePrice}}</b></span><em :class="`is-${row.changeColor}`">{{row.changeLabel}}</em><span><small>تغير 30 يوم</small><b :class="deltaTone(row.delta30)">{{row.delta30===null?'—':`${row.delta30>0?'+':''}${row.delta30}%`}}</b></span><time>{{row.date}}<small>{{row.ago}}</small></time><i class="bi bi-chevron-left"></i></a></div><EmptyState v-else icon="bi-tag" title="لا أسعار مسجلة" message="تظهر تلقائياً بعد أول استلام من هذا المورد."/></DataPanel></template>
<style scoped>.supplier-prices{display:grid;gap:6px}.supplier-prices>a{display:grid;grid-template-columns:minmax(150px,1.2fr) repeat(2,minmax(130px,1fr)) auto minmax(100px,.7fr) 100px 14px;align-items:center;gap:9px;padding:11px;border:1px solid #e1e8e3;border-radius:12px;color:#34463b;background:#fff}.supplier-prices div,.supplier-prices span,.supplier-prices time{display:grid}.supplier-prices strong,.supplier-prices b{font-size:.63rem}.supplier-prices small{color:#829087;font-size:.55rem}.supplier-prices .green,.supplier-prices .down{color:#176b39}.supplier-prices .up{color:#b42318}.supplier-prices .muted{color:#7c8981}.supplier-prices em{padding:3px 6px;border-radius:99px;font-size:.53rem;font-style:normal;font-weight:800}.is-success{color:#176b39;background:#e7f5eb}.is-danger{color:#b42318;background:#feecec}.is-warning{color:#955900;background:#fff0d2}.is-secondary{color:#68776e;background:#edf0ee}@media(max-width:850px){.supplier-prices>a{grid-template-columns:1fr 1fr 14px}.supplier-prices>a>div{grid-column:1/-2}.supplier-prices>a>span:nth-of-type(n+3),.supplier-prices>a>em,.supplier-prices>a>time{display:none}}@media(max-width:500px){.supplier-prices>a{grid-template-columns:1fr 14px}.supplier-prices>a>span:nth-of-type(2){display:none}}</style>
